"""Glossary lookup for Automated Personalized Drug Manufacturing."""

GLOSSARY = {
    "biomarker": "a measurable indicator of a biological state or condition",
    "closed loop": "a system where sensing automatically adjusts therapy without manual steps",
    "efficacy": "how well a therapy works under controlled study conditions",
    "pharmacokinetics": "how the body absorbs, distributes, and clears a therapy",
    "digital twin": "a computational patient model used to predict treatment response",
    "adverse event": "any unfavorable medical occurrence during treatment, investigated for cause",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Automated Personalized Drug Manufacturing glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Diagnostic Sensing — part of the Automated Personalized Drug Manufacturing system."""
import random

class AutomatedPersonalizedDrugManufacturingPiece1DiagnosticSensing:
    """Models the Diagnostic Sensing piece: specification check and behavior sample."""

    SPEC = {"piece": "Diagnostic Sensing", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = AutomatedPersonalizedDrugManufacturingPiece1DiagnosticSensing(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Diagnostic Sensing — Automated Personalized Drug Manufacturing")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

