"""Data processing pipeline model — model for Automated Personalized Drug Manufacturing.
Domain: medicine and human health. Deterministic demonstration model (seeded).
"""
import random

class AutomatedPersonalizedDrugManufacturingSim:
    """Ingest -> validate -> transform -> analyze -> report pipeline."""

    def __init__(self, seed=7):
        self.rng = random.Random(seed)
        self.stages = ["ingest", "validate", "transform", "analyze", "report"]
        self.counts = {s: 0 for s in self.stages}
        self.dropped = 0

    def ingest(self, n):
        return [{"id": i, "value": self.rng.gauss(50, 12),
                 "flag": self.rng.random() < 0.06} for i in range(n)]

    def validate(self, records):
        good = [r for r in records if -20 < r["value"] < 120 and not r["flag"]]
        self.dropped += len(records) - len(good)
        return good

    def transform(self, records):
        return [{"id": r["id"], "score": round((r["value"] - 50) / 12, 3)} for r in records]

    def analyze(self, records):
        scores = [r["score"] for r in records]
        mean = sum(scores) / len(scores)
        var = sum((s - mean) ** 2 for s in scores) / len(scores)
        alerts = [r for r in records if abs(r["score"]) > 2.5]
        return {"n": len(records), "mean": round(mean, 3),
                "std": round(var ** 0.5, 3), "alerts": len(alerts)}

    def run(self, n=500):
        data = self.ingest(n)
        for s in ["validate", "transform"]:
            self.counts[s] += 1
        data = self.transform(self.validate(data))
        self.counts["analyze"] += 1
        result = self.analyze(data)
        result["dropped_invalid"] = self.dropped
        return result


if __name__ == "__main__":
    p = AutomatedPersonalizedDrugManufacturingSim(seed=7)
    r = p.run(500)
    print("Automated Personalized Drug Manufacturing data pipeline model")
    print("records:", r["n"], "| mean:", r["mean"], "| std:", r["std"],
          "| alerts:", r["alerts"], "| dropped:", r["dropped_invalid"])
